+func getTrivyCveContents(vuln types.DetectedVulnerability) models.CveContents {
+	references := make(models.References, 0, len(vuln.References))
+	for _, reference := range vuln.References {
+		references = append(references, models.Reference{Source: "trivy", Link: reference})
+	}
+	sort.Slice(references, func(i, j int) bool {
+		return references[i].Link < references[j].Link
+	})
+
+	var published, lastModified time.Time
+	if vuln.PublishedDate != nil {
+		published = *vuln.PublishedDate
+	}
+	if vuln.LastModifiedDate != nil {
+		lastModified = *vuln.LastModifiedDate
+	}
+
+	sources := map[trivydbTypes.SourceID]struct{}{}
+	for source := range vuln.VendorSeverity {
+		sources[source] = struct{}{}
+	}
+	for source := range vuln.CVSS {
+		sources[source] = struct{}{}
+	}
+	if vuln.SeveritySource != "" {
+		sources[vuln.SeveritySource] = struct{}{}
+	}
+	if vuln.DataSource != nil && vuln.DataSource.ID != "" {
+		sources[vuln.DataSource.ID] = struct{}{}
+	}
+	if len(sources) == 0 {
+		sources["trivy"] = struct{}{}
+	}
+
+	contents := models.CveContents{}
+	for source := range sources {
+		ctype := models.Trivy
+		if source != "trivy" {
+			ctype = models.NewCveContentType("trivy:" + string(source))
+		}
+
+		severity := ""
+		if vendorSeverity, ok := vuln.VendorSeverity[source]; ok {
+			severity = vendorSeverity.String()
+		} else if source == vuln.SeveritySource || (source == "trivy" && len(vuln.VendorSeverity) == 0) {
+			severity = vuln.Severity
+		}
+		cvss := vuln.CVSS[source]
+		contents[ctype] = []models.CveContent{{
+			Type:          ctype,
+			CveID:         vuln.VulnerabilityID,
+			Title:         vuln.Title,
+			Summary:       vuln.Description,
+			Cvss2Score:    cvss.V2Score,
+			Cvss2Vector:   cvss.V2Vector,
+			Cvss3Score:    cvss.V3Score,
+			Cvss3Vector:   cvss.V3Vector,
+			Cvss3Severity: severity,
+			References:    references,
+			Published:     published,
+			LastModified:  lastModified,
+		}}
+	}
+	return contents
+}
+
+func mergeTrivyCveContent(existing, incoming models.CveContent) models.CveContent {
+	if incoming.Title != "" {
+		existing.Title = incoming.Title
+	}
+	if incoming.Summary != "" {
+		existing.Summary = incoming.Summary
+	}
+	if incoming.Cvss2Score != 0 {
+		existing.Cvss2Score = incoming.Cvss2Score
+	}
+	if incoming.Cvss2Vector != "" {
+		existing.Cvss2Vector = incoming.Cvss2Vector
+	}
+	if incoming.Cvss3Score != 0 {
+		existing.Cvss3Score = incoming.Cvss3Score
+	}
+	if incoming.Cvss3Vector != "" {
+		existing.Cvss3Vector = incoming.Cvss3Vector
+	}
+	if incoming.Cvss3Severity != "" {
+		existing.Cvss3Severity = incoming.Cvss3Severity
+	}
+	if !incoming.Published.IsZero() {
+		existing.Published = incoming.Published
+	}
+	if !incoming.LastModified.IsZero() {
+		existing.LastModified = incoming.LastModified
+	}
+	for _, reference := range incoming.References {
+		found := false
+		for _, oldReference := range existing.References {
+			if oldReference.Link == reference.Link {
+				found = true
+				break
+			}
+		}
+		if !found {
+			existing.References = append(existing.References, reference)
+		}
+	}
+	sort.Slice(existing.References, func(i, j int) bool {
+		return existing.References[i].Link < existing.References[j].Link
+	})
+	return existing
+}
